12	import { findLatestLog } from "../utils/logScanner";
13	interface CheckAndClaimParams {
14	  chainId: number;
15	  network: Network;
16	  claim: ClaimStruct | null;
17	  epochPeriod: number;
18	  epoch: number;
19	  veaInbox: any;
20	  veaInboxProvider: JsonRpcProvider;
21	  veaOutbox: any;
22	  veaOutboxProvider: JsonRpcProvider;
23	  veaRouterProvider?: JsonRpcProvider;
24	  transactionHandler: ITransactionHandler | null;
25	  emitter: EventEmitter;
26	  fetchClaim?: typeof getClaim;
27	  fetchLatestClaimedEpoch?: typeof getLastClaimedEpoch;
28	  fetchTransactionHandler?: typeof getTransactionHandler;
29	  fetchBlocksAndCheckFinality?: typeof getBlocksAndCheckFinality;
30	  fetchSettledReadBlocks?: typeof resolveSettledReadBlocks;
31	  now?: number;
32	}
