34	async function checkAndClaim({
35	  chainId,
36	  network,
37	  claim,
38	  epoch,
39	  epochPeriod,
40	  veaInbox,
41	  veaInboxProvider,
42	  veaOutbox,
43	  veaOutboxProvider,
44	  transactionHandler,
45	  emitter,
46	  veaRouterProvider,
47	  fetchLatestClaimedEpoch = getLastClaimedEpoch,
48	  fetchTransactionHandler = getTransactionHandler,
49	  fetchBlocksAndCheckFinality = getBlocksAndCheckFinality,
50	  fetchSettledReadBlocks = resolveSettledReadBlocks,
51	  now = Date.now(),
52	}: CheckAndClaimParams) {
53	  let outboxStateRoot = await veaOutbox.stateRoot();
54	  const claimAbleEpoch = Math.floor(now / (1000 * epochPeriod)) - 1;
55	  if (!transactionHandler) {
56	    const TransactionHandler = fetchTransactionHandler(chainId, network);
57	    transactionHandler = new TransactionHandler({
58	      chainId,
59	      network,
60	      epoch,
61	      veaInbox,
62	      veaOutbox,
63	      veaInboxProvider,
64	      veaOutboxProvider,
65	      emitter,
66	      claim,
67	    });
68	  } else {
69	    transactionHandler.claim = claim;
70	  }
71	  if (network == Network.DEVNET) {
72	    return makeClaimDevnet(
73	      epoch,
74	      claim,
75	      outboxStateRoot,
76	      transactionHandler as IDevnetTransactionHandler,
77	      veaInbox,
78	      emitter
79	    );
80	  } else if (claim == null && epoch == claimAbleEpoch) {
81	    const queryRpc = veaRouterProvider ?? veaOutboxProvider;
82	    return makeClaim(
83	      chainId,
84	      epoch,
85	      epochPeriod,
86	      transactionHandler,
87	      veaInbox,
88	      veaOutbox,
89	      veaOutboxProvider,
90	      queryRpc,
91	      emitter,
92	      fetchLatestClaimedEpoch,
93	      fetchBlocksAndCheckFinality,
94	      fetchSettledReadBlocks
95	    );
96	  } else if (claim != null) {
97	    return verifyClaim(transactionHandler, claim, veaOutboxProvider);
98	  } else {
99	    emitter.emit(BotEvents.CLAIM_EPOCH_PASSED, epoch);
100	  }
101	  return null;
102	}
103	
104	async function makeClaimDevnet(
105	  epoch: number,
106	  claim: ClaimStruct | null,
107	  outboxStateRoot: string,
108	  transactionHandler: IDevnetTransactionHandler,
109	  veaInbox: any,
110	  emitter: EventEmitter
111	): Promise<IDevnetTransactionHandler | null> {
112	  if (claim == null) {
113	    const [savedSnapshot] = await Promise.all([veaInbox.snapshots(epoch)]);
114	
115	    const newMessagesToBridge = savedSnapshot != outboxStateRoot && savedSnapshot != ethers.ZeroHash;
116	    if (newMessagesToBridge && savedSnapshot != ethers.ZeroHash) {
117	      await transactionHandler.devnetAdvanceState(savedSnapshot);
118	      return transactionHandler;
119	    }
120	  }
121	  emitter.emit(BotEvents.NO_CLAIM_REQUIRED, epoch);
122	  return null;
123	}
124	
125	async function makeClaim(
126	  chainId: number,
127	  epoch: number,
128	  epochPeriod: number,
129	  transactionHandler: ITransactionHandler,
