1	import { JsonRpcProvider, Block } from "@ethersproject/providers";
2	import { SequencerInbox } from "@arbitrum/sdk/dist/lib/abi/SequencerInbox";
3	import { NodeInterface__factory } from "@arbitrum/sdk/dist/lib/abi/factories/NodeInterface__factory";
4	import { NodeInterface } from "@arbitrum/sdk/dist/lib/abi/NodeInterface";
5	import { NODE_INTERFACE_ADDRESS } from "@arbitrum/sdk/dist/lib/dataEntities/constants";
6	import { getArbitrumNetwork } from "@arbitrum/sdk";
7	import { SequencerInbox__factory } from "@arbitrum/sdk/dist/lib/abi/factories/SequencerInbox__factory";
8	import { defaultEmitter } from "../utils/emitter";
9	import { BotEvents } from "../utils/botEvents";
10	import { findFirstLog } from "./logScanner";
11	
12	// https://github.com/prysmaticlabs/prysm/blob/493905ee9e33a64293b66823e69704f012b39627/config/params/mainnet_config.go#L103
13	const slotsPerEpochEth = 32;
14	const secondsPerSlotEth = 12;
15	
16	export interface SettledReadBlocks {
17	  inboxBlock: number;
18	  outboxBlock: number;
19	}
20	
21	export interface ResolveSettledReadBlocksParams {
22	  inboxProvider: JsonRpcProvider;
23	  outboxProvider: JsonRpcProvider;
24	  epoch: number;
25	  epochPeriod: number;
26	  emitter?: typeof defaultEmitter;
27	  fetchBlocksAndCheckFinality?: typeof getBlocksAndCheckFinality;
28	}
29	
30	/**
31	 * Resolve the blocks at which this epoch's state can be read as settled.
32	 *
33	 * Two conditions have to hold before a read can be staked on:
34	 *
35	 *  - the block cannot be reorged away, so we anchor to the `finalized` head on
36	 *    both chains;
37	 *  - the block must sit at or after `(epoch + 1) * epochPeriod`, because
38	 *    `snapshots[epoch]` is still being written during epoch E.
39	 *
40	 * When either fails the epoch is simply not decidable yet: callers skip it and
41	 * try again next cycle rather than acting on unsettled state.
42	 *
43	 * @returns The blocks to pin reads to, or null if the epoch is not yet decidable
44	 */
45	export const resolveSettledReadBlocks = async ({
46	  inboxProvider,
47	  outboxProvider,
48	  epoch,
49	  epochPeriod,
50	  emitter = defaultEmitter,
51	  fetchBlocksAndCheckFinality = getBlocksAndCheckFinality,
52	}: ResolveSettledReadBlocksParams): Promise<SettledReadBlocks | null> => {
53	  const finality = await fetchBlocksAndCheckFinality(outboxProvider, inboxProvider, epoch, epochPeriod, emitter);
54	  // Checked before destructuring: this returns undefined on an unresolvable
55	  // chain state, and destructuring that throws past every caller's guard.
56	  if (!finality) {
57	    emitter.emit(BotEvents.FINALITY_ISSUE, epoch);
58	    return null;
59	  }
60	  const [inboxFinalized, outboxFinalized, finalityIssueFlagArb, finalityIssueFlagEth] = finality;
61	  if (finalityIssueFlagArb || finalityIssueFlagEth) {
62	    emitter.emit(BotEvents.FINALITY_ISSUE, epoch);
63	    return null;
64	  }
65	
66	  const epochBoundary = (epoch + 1) * epochPeriod;
67	  if (inboxFinalized.timestamp < epochBoundary) {
68	    emitter.emit(BotEvents.EPOCH_NOT_SETTLED, epoch, inboxFinalized.timestamp, epochBoundary);
69	    return null;
70	  }
71	
72	  return { inboxBlock: inboxFinalized.number, outboxBlock: outboxFinalized.number };
73	};
74	
75	/**
76	 * The sequencer's maximum backdating window, in seconds.
77	 *
78	 * `maxTimeVariation()` returns four values -- [delayBlocks, futureBlocks,
79	 * delaySeconds, futureSeconds] -- so coercing the whole result yields NaN, which
80	 * then silently poisons every block range derived from it.
81	 *
82	 * @returns delaySeconds from the sequencer inbox
83	 */
84	const getSequencerDelaySeconds = async (sequencer: SequencerInbox): Promise<number> => {
85	  const { delaySeconds } = await sequencer.maxTimeVariation();
86	  return Number(delaySeconds);
87	};
88	
89	/**
90	 * This function checks the finality of the blocks on Arbitrum and Ethereum.
91	 * It returns the latest/finalized block on Arbitrum(found on Ethereum) and Ethereum and a flag indicating if there is a finality issue on Ethereum.
92	 *
93	 * @param EthProvider Ethereum provider
94	 * @param ArbProvider Arbitrum provider
95	 * @param veaEpoch epoch number of the claim to be fetched
96	 * @param veaEpochPeriod epoch period of the claim to be fetched
97	 *
98	 * @returns [Arbitrum block, Ethereum block, finalityIssueFlagArb, finalityIssueFlagEth]
99	 * */
100	const getBlocksAndCheckFinality = async (
101	  EthProvider: JsonRpcProvider,
102	  ArbProvider: JsonRpcProvider,
103	  veaEpoch: number,
104	  veaEpochPeriod: number,
105	  emitter: typeof defaultEmitter
106	): Promise<[Block, Block, boolean, boolean] | undefined> => {
107	  const currentEpoch = Math.floor(Date.now() / 1000 / veaEpochPeriod);
108	
109	  const l2Network = await getArbitrumNetwork(ArbProvider);
110	  const sequencer = SequencerInbox__factory.connect(l2Network.ethBridge.sequencerInbox, EthProvider);
111	  const maxDelaySeconds = await getSequencerDelaySeconds(sequencer);
112	  const blockFinalizedArb = (await ArbProvider.getBlock("finalized")) as Block;
113	  const blockFinalizedEth = (await EthProvider.getBlock("finalized")) as Block;
114	  if (
115	    currentEpoch - veaEpoch > 2 &&
116	    blockFinalizedArb.timestamp > veaEpoch * veaEpochPeriod &&
117	    blockFinalizedEth.timestamp > veaEpoch * veaEpochPeriod
118	  ) {
119	    return [blockFinalizedArb, blockFinalizedEth, false, false];
120	  }
121	  const finalityBuffer = 300; // 5 minutes, allows for network delays
122	  const maxFinalityTimeSecondsEth = slotsPerEpochEth * 2 * secondsPerSlotEth; // finalization after 2 justified epochs
123	
124	  let finalityIssueFlagArb = false;
125	  let finalityIssueFlagEth = false;
126	
127	  // check latest arb block to see if there are any sequencer issues
128	  let blockLatestArb = (await ArbProvider.getBlock("latest")) as Block;
129	
130	  const maxDelayInSeconds = 7 * 24 * 60 * 60; // 7 days
131	  let blockoldArb = (await ArbProvider.getBlock(blockLatestArb.number - 100)) as Block;
132	  const arbAverageBlockTime = (blockLatestArb.timestamp - blockoldArb.timestamp) / 100;
133	  const fromBlockArbFinalized = blockFinalizedArb.number - Math.ceil(maxDelayInSeconds / arbAverageBlockTime);
134	  // to performantly query the sequencerInbox's SequencerBatchDelivered event on Eth, we limit the block range
135	  // we use the heuristic that. delta blocknumber <= delta timestamp / secondsPerSlot
136	  // Arb: -----------x                   <-- Finalized
137	  //                 ||
138	  //                 \/
139	  // Eth: -------------------------x     <-- Finalized
140	  //            /\
141	  //            ||<---------------->     <-- Math.floor((timeDiffBlockFinalizedArbL1 + maxDelaySeconds) / secondsPerSlotEth)
142	  //         fromBlockEth
143	
144	  const timeDiffBlockFinalizedArbL1 = blockFinalizedEth.timestamp - blockFinalizedArb.timestamp;
145	  const fromBlockEthFinalized =
146	    blockFinalizedEth.number - Math.floor((timeDiffBlockFinalizedArbL1 + maxDelaySeconds) / secondsPerSlotEth);
147	
148	  let blockFinalizedArbToL1Block = await ArbBlockToL1Block(
149	    ArbProvider,
150	    sequencer,
151	    blockFinalizedArb,
152	    fromBlockEthFinalized,
153	    fromBlockArbFinalized,
154	    false
155	  );
156	
157	  if (!blockFinalizedArbToL1Block) {
158	    emitter.emit(BotEvents.FINALITY_ERROR, "Arbitrum finalized block is not found on L1.");
159	    finalityIssueFlagArb = true;
160	  } else if (Math.abs(blockFinalizedArbToL1Block[0].timestamp - blockFinalizedArb.timestamp) > 1800) {
161	    // The L2 timestamp is drifted from the L1 timestamp in which the L2 block is posted.
162	    emitter.emit(BotEvents.FINALITY_ERROR, "Finalized L2 block time is more than 30 min drifted from L1 clock.");
163	  }
164	
165	  // blockLatestArbToL1Block[0] is the L1 block, blockLatestArbToL1Block[1] is the L2 block (fallsback on latest L2 block if L2 block is not found on L1)
166	  let blockLatestArbToL1Block = await ArbBlockToL1Block(
167	    ArbProvider,
168	    sequencer,
169	    blockLatestArb,
170	    fromBlockEthFinalized,
171	    fromBlockArbFinalized,
172	    true
173	  );
174	
175	  if (finalityIssueFlagArb && !blockLatestArbToL1Block) {
176	    emitter.emit(BotEvents.FINALITY_ERROR, "Arbitrum latest block is not found on L1.");
177	    // this means some issue in the arbitrum node implementation (very bad)
178	    return undefined;
179	  }
180	
181	  // is blockLatestArb is not found on L1, ArbBlockToL1Block fallsback on the latest L2 block found on L1
182	  if (blockLatestArbToL1Block[1] != blockLatestArb.number) {
183	    blockLatestArb = (await ArbProvider.getBlock(blockLatestArbToL1Block[1])) as Block;
184	  }
185	
186	  // ETH POS assumes synchronized clocks
187	  // using local time as a proxy for true "latest" L1 time
188	  const localTimeSeconds = Math.floor(Date.now() / 1000);
189	
190	  // The sequencer is completely offline
191	  if (localTimeSeconds - blockLatestArbToL1Block[0].timestamp > 1800) {
192	    emitter.emit(
193	      BotEvents.FINALITY_ERROR,
